// spec: specs/admin-subscriptions.md (раздел 1.1)
// seed: tests/seed.admin.spec.ts
// Расхождения плана с живой страницей (19.11.2026):
//  - в плитке «מנויי Premium פעילים» вместо «מהחודש הקודם» подпись «אין היסטוריית מנויים עדיין» (в остальных плитках — «חדש» + «מהחודש הקודם»);
//  - активных подписок 5 (в плане «3 Premium»), поэтому проверяем структуру, а не точные числа;
//  - у вкладок «תשלום נכשל» и «בוטלו» счётчика нет (счётчик есть у «כל המנויים» и «מתחדש השבוע»).
// Только просмотр: «הענקת …», «⋯», «כלי בדיקה» не нажимаются.
import { test, expect } from '@playwright/test';
import path from 'path';

const ADMIN_URL = 'https://magnet-admin.vercel.app';

test.use({ storageState: path.resolve(__dirname, '../../../auth/admin-r11.json') });

test.describe('Админка: «מנויים ורכישות» (#01f23b)', () => {
  test('Страница: меню, заголовок, плитки, вкладки, поиск, колонки @desktop @prod-safe', async ({ page }) => {
    await page.goto(`${ADMIN_URL}/users`);

    // 1. В меню слева нажать «מנויים ורכישות»
    const menuLink = page.getByRole('navigation', { name: 'ניווט ראשי' }).getByRole('link', { name: 'מנויים ורכישות' });
    await menuLink.click();
    await expect(page).toHaveURL(/\/subscriptions$/);

    // 2. Шапка, плитки, вкладки, таблица
    await expect(menuLink).toHaveAttribute('aria-current', 'page');
    await expect(page.getByRole('heading', { level: 1, name: 'מנויים ורכישות' })).toBeVisible();
    await expect(page.getByText('הכנסות ורכישות ב־30 הימים האחרונים')).toBeVisible();

    for (const tile of ['הכנסות', 'מנויי Premium פעילים', 'בוסטים וסופר לייק', 'מתנות']) {
      await expect(page.getByText(tile, { exact: true })).toBeVisible();
    }
    await expect(page.getByText(/^₪[\d,]+\.\d\d$/).first()).toBeVisible();
    await expect(page.getByText('מהחודש הקודם').first()).toBeVisible();

    const region = page.getByRole('region', { name: 'מנויים' });
    const allTab = region.getByRole('tab', { name: /^כל המנויים\s*\d+$/ });
    await expect(allTab).toHaveAttribute('aria-selected', 'true');
    await expect(region.getByRole('tab', { name: /^מתחדש השבוע\s*\d+$/ })).toBeVisible();
    await expect(region.getByRole('tab', { name: 'תשלום נכשל' })).toBeVisible();
    await expect(region.getByRole('tab', { name: 'בוטלו' })).toBeVisible();

    await expect(region.getByRole('textbox', { name: 'חיפוש לפי שם, טלפון או מזהה' })).toBeVisible();
    await expect(region.getByText('מסננים', { exact: true })).toBeVisible();

    for (const col of ['משתמש/ת', 'מסלול', 'תקופה', 'חידוש', 'תשלום', 'רכישות נוספות', 'שדכנית']) {
      await expect(region.getByRole('columnheader', { name: col, exact: true })).toBeVisible();
    }

    const total = Number((await allTab.innerText()).replace(/\D/g, ''));
    await expect(region.getByText(new RegExp(`מוצגים 1–${total} מתוך ${total}`))).toBeVisible();
    await expect(region.getByText(/\d+ בעמוד/)).toBeVisible();
    await expect(region.getByRole('row')).toHaveCount(total + 1);
  });
});
